mapper.select:
select  from t_ai_chat_session s where 
and s.acs_id < #{before}
order by s.acs_id desc limit 21

select acm_id as id,case acm_role when 1 then 'user' else 'assistant' end as role,
    acm_content as content,case when acm_role=2 then right(acm_intent,1) else null end as state
from t_ai_chat_message where acm_session_id=#{sessionId} and acm_role in (1,2)
and acm_id < #{before}
order by acm_id desc limit #{limit}

select t.tal_id as candidateId, u.nick_name as candidateName, p.pos_title as positionTitle, a.app_status as applicationStatus, t.tal_status as talentStatus from t_tal t join sys_user u on u.user_id=t.tal_user_id left join t_app_record a on a.app_id=(select max(a2.app_id) from t_app_record a2 where a2.app_candidate_id=t.tal_id) left join t_pos p on p.pos_id=a.app_position_id and p.pos_company_id=#{companyId} where t.tal_company_id=#{companyId}
and (u.nick_name like concat('%',#{keyword},'%') or p.pos_title like concat('%',#{keyword},'%'))
order by t.tal_id desc limit #{limit}
